-- HolaMate: Insert 65 menu items for 10 fixed_shop vendors
-- Run in Supabase Dashboard > SQL Editor


-- Verify
SELECT v.name, COUNT(mi.id) as menu_count
FROM vendors v
LEFT JOIN menu_items mi ON mi.vendor_id = v.id
WHERE v.vendor_type = 'fixed_shop'
GROUP BY v.id, v.name
ORDER BY menu_count DESC;
